import{_ as t,o as a,c as o,a2 as i}from"./chunks/framework.Bg-Zxr5O.js";const p=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/MCONVERT.md","filePath":"manual-en/MCONVERT.md","lastUpdated":1785684581000}'),r={name:"manual-en/MCONVERT.md"};function n(d,e,c,s,l,m){return a(),o("div",null,[...e[0]||(e[0]=[i(`<h3 id="_16-3-mconvert" tabindex="-1">16.3 MCONVERT <a class="header-anchor" href="#_16-3-mconvert" aria-label="Permalink to &quot;16.3 MCONVERT&quot;">​</a></h3><pre><code>MCONVERT
    [[MATRIX=]
     [IN({‘*’|’file’})]
     [OUT({‘*’|’file’})]]
    [/{REPLACE,APPEND}].
</code></pre><p>The <code>MCONVERT</code> command converts matrix data from a correlation matrix and a vector of standard deviations into a covariance matrix, or vice versa.</p><p>By default, <code>MCONVERT</code> both reads and writes the active file. Use the <code>MATRIX</code> subcommand to specify other files. To read a matrix file, specify its name inside parentheses following <code>IN</code>. To write a matrix file, specify its name inside parentheses following <code>OUT</code>. Use ‘*’ to explicitly specify the active file for input or output.</p><p>When <code>MCONVERT</code> reads the input, by default it substitutes a correlation matrix and a vector of standard deviations each time it encounters a covariance matrix, and vice versa. Specify <code>/APPEND</code> to instead have <code>MCONVERT</code> add the other form of data without removing the existing data. Use <code>/REPLACE</code> to explicitly request removing the existing data.</p><p>The <code>MCONVERT</code> command requires its input to be a matrix file. Use <code>MATRIX DATA</code> to convert text input into matrix file format. See <a href="./MATRIX-DATA">MATRIX DATA</a>, for details.</p>`,6)])])}const T=t(r,[["render",n]]);export{p as __pageData,T as default};
